def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my_def = 0
    opp_def = 0
    for a, o in history:
        if a == 'D':
            my_def += 1
        if o == 'D':
            opp_def += 1
    forgiven = False
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i+1][1] == 'C':
            forgiven = True
            break
    if forgiven:
        return 'D'
    if opp_def / n > 0.5:
        return 'D'
    if n >= 99:
        return 'D'
    last_opp = history[-1][1]
    if last_opp == 'C':
        return 'C'
    consec = 0
    for _, o in reversed(history):
        if o == 'D':
            consec += 1
        else:
            break
    if consec == 1:
        if opp_def / n < 0.3:
            return 'C'
        else:
            return 'D'
    elif consec == 2:
        return 'D'
    elif consec == 3:
        return 'D'
    elif consec == 4:
        return 'C'
    else:
        if opp_def / n > 0.35:
            return 'D'
        else:
            return 'C'
